// Symbolic runtime for executing Hex-Rays pseudocode of FaceTrackerInternal.dll's hard-coded
// cascade functions (generated by ldmf/extract/build_structure.py; see docs/winhello-models/ldmf.md).

#include <cstdio>
#include <cstdlib>
#include <vector>
#include <string>
typedef long long ll;
static int funit=4;
enum Kind {INT=0, PTR=1, LIN=2, SCORE=3, FIDX=4, FADDR=5, TEST=6, MASK=7};
static void die(const char* m);
struct R;
struct V {
  int k; ll c; int img; int na; ll ex=0; int ti[2]; ll to[2]; int ts[2]; int fid;
  V(): k(INT), c(0), img(-1), na(0), fid(-1) {}
  V(ll x): k(INT), c(x), img(-1), na(0), fid(-1) {}
  V(int x): k(INT), c(x), img(-1), na(0), fid(-1) {}
  V(unsigned x): k(INT), c(x), img(-1), na(0), fid(-1) {}
  V(unsigned long long x): k(INT), c((ll)x), img(-1), na(0), fid(-1) {}
  V(bool x): k(INT), c(x), img(-1), na(0), fid(-1) {}
  struct R operator[](const V& i) const;
  explicit operator bool() const { if(k!=INT) die("bool"); return c!=0; }
};
static void die(const char* m);
static void die_(const char* m){ fprintf(stderr,"DIE %s\n",m); exit(3);}
static void die(const char* m){ die_(m); }
static V mkptr(int img, ll off){ V v; v.k=PTR; v.img=img; v.c=off; return v; }
// ---- logging/oracle
struct Test { int na; int ti[2]; ll to[2]; int ts[2]; ll thr; };
static std::vector<Test> tests;            // fern tests
static std::vector<std::vector<int>> masks; // fern masks (8 test ids)
static int cur_tree=0, target=-1, dcount=0; static std::vector<int> plan; static std::vector<int> taken;
static void plin(const V& v){ printf("["); for(int i=0;i<v.na;i++) printf("%s[%d,%d,%lld]", i?",":"", v.ts[i], v.ti[i], v.to[i]); printf("]"); }
static V addlin(const V& a, const V& b, int sb){ // a + sb*b, both LIN or INT
  V r; r.k=LIN; r.c=a.c+sb*b.c; r.na=0;
  auto add=[&](int img, ll off, int s){ for(int i=0;i<r.na;i++) if(r.ti[i]==img&&r.to[i]==off){ r.ts[i]+=s; if(!r.ts[i]){ for(int j=i;j<r.na-1;j++){r.ti[j]=r.ti[j+1];r.to[j]=r.to[j+1];r.ts[j]=r.ts[j+1];} r.na--; } return;} if(r.na>=2) die("lin>2"); r.ti[r.na]=img; r.to[r.na]=off; r.ts[r.na]=s; r.na++; };
  if(a.k==LIN) for(int i=0;i<a.na;i++) add(a.ti[i],a.to[i],a.ts[i]);
  if(b.k==LIN) for(int i=0;i<b.na;i++) add(b.ti[i],b.to[i],sb*b.ts[i]);
  if(r.na==0) r.k=INT;
  return r;
}
// decision: returns truth of (L <= t) where L = linear pixel part; called with lin V (c ignored) and t
static bool decide_le(const V& L, ll t){
  if(cur_tree!=target) return true;
  int i=dcount++; bool ans = i<(int)plan.size()? plan[i] : true;
  taken.push_back(ans);
  printf("N %d %d ", cur_tree, i); plin(L); printf(" %lld %d\n", t, (int)ans);
  return ans;
}
static bool cmp(const V& a, const V& b, int op){ // op: 0 <=,1 <,2 >,3 >=,4 ==,5 !=
  if(a.k==INT && b.k==INT){ ll x=a.c,y=b.c; switch(op){case 0:return x<=y;case 1:return x<y;case 2:return x>y;case 3:return x>=y;case 4:return x==y;default:return x!=y;} }
  if(a.k==SCORE || b.k==SCORE){
    if(a.k==SCORE && b.k==INT){ printf("S %d %d %lld\n", cur_tree, op, b.c); return op==2||op==3||op==5; }
    die("score cmp");
  }
  if((a.k==LIN||a.k==INT)&&(b.k==LIN||b.k==INT)){
    V L=addlin(a,b,-1); if(L.k==INT) return cmp(V(L.c),V(0LL),op);
    ll c=L.c; V P=L; P.c=0;
    switch(op){ case 0: return decide_le(P,-c); case 1: return decide_le(P,-c-1); case 2: return !decide_le(P,-c); case 3: return !decide_le(P,-c-1); default: die("eq on lin"); }
  }
  die("cmp kinds"); return false;
}
static bool operator<=(const V&a,const V&b){return cmp(a,b,0);}
static bool operator<(const V&a,const V&b){return cmp(a,b,1);}
static bool operator>(const V&a,const V&b){return cmp(a,b,2);}
static bool operator>=(const V&a,const V&b){return cmp(a,b,3);}
static bool operator==(const V&a,const V&b){return cmp(a,b,4);}
static bool operator!=(const V&a,const V&b){return cmp(a,b,5);}
static V operator+(const V&a,const V&b){
  if(a.k==INT&&b.k==INT) return V(a.c+b.c);
  if(a.k==PTR&&b.k==INT) return mkptr(a.img,a.c+b.c);
  if(a.k==INT&&b.k==PTR) return mkptr(b.img,a.c+b.c);
  if(a.k==SCORE||b.k==SCORE){ V r; r.k=SCORE; return r; }
  if(a.k==FADDR&&b.k==INT){ V r=a; r.c+=b.c; return r; }
  if(a.k==INT&&b.k==FADDR){ V r=b; r.c+=a.c; return r; }
  if(a.k==FIDX&&b.k==INT){ V r=a; r.ex+=b.c; return r; }
  if(a.k==INT&&b.k==FIDX){ V r=b; r.ex+=a.c; return r; }
  if((a.k==PTR&&b.k==FIDX)||(a.k==FIDX&&b.k==PTR)){ const V& p=a.k==PTR?a:b; const V& f=a.k==FIDX?a:b; V r; r.k=FADDR; r.img=p.img; r.c=p.c+f.ex; r.fid=f.fid; if(f.c!=4) die("fidx scale"); return r; }
  if((a.k==LIN||a.k==INT)&&(b.k==LIN||b.k==INT)) return addlin(a,b,1);
  fprintf(stderr,"add %d %d\n",a.k,b.k); die("add kinds"); return V();
}
static V operator-(const V&a,const V&b){
  if(a.k==INT&&b.k==INT) return V(a.c-b.c);
  if(a.k==PTR&&b.k==INT) return mkptr(a.img,a.c-b.c);
  if((a.k==LIN||a.k==INT)&&(b.k==LIN||b.k==INT)) return addlin(a,b,-1);
  die("sub kinds"); return V();
}
static V operator-(const V&a){ return V(0LL)-a; }
static V operator*(const V&a,const V&b){
  if(a.k==INT&&b.k==INT) return V(a.c*b.c);
  if(a.k==INT&&b.k==FIDX){ V r=b; r.c*=a.c; r.ex*=a.c; return r; }
  die("mul kinds"); return V();
}
static V operator<<(const V&a,const V&b){ if(a.k==INT&&b.k==INT) return V(a.c<<b.c); die("shl"); return V(); }
static V operator>>(const V&a,const V&b){
  if(a.k==INT&&b.k==INT) return V(a.c>>b.c);
  if(a.k==LIN&&b.k==INT&&b.c==31){ return V((ll)(a < V(0LL) ? -1 : 0)); }
  die("shr"); return V(); }
static V operator&(const V&a,const V&b){ if(a.k==INT&&b.k==INT) return V(a.c&b.c); die("and"); return V(); }
static V operator|(const V&a,const V&b){ if(a.k==INT&&b.k==INT) return V(a.c|b.c); die("or"); return V(); }
static V operator^(const V&a,const V&b){ if(a.k==INT&&b.k==INT) return V(a.c^b.c); die("xor"); return V(); }
static V& operator+=(V&a,const V&b){ a=a+b; return a; }
static V& operator-=(V&a,const V&b){ a=a-b; return a; }
static int weight_img=10, fernw_img=11;
static V deref(const V& p){
  if(p.k==PTR && p.img>=0 && p.img<3){ V r; r.k=LIN; r.na=1; r.ti[0]=p.img; r.to[0]=p.c; r.ts[0]=1; r.c=0; return r; }
  if(p.k==PTR && p.img==weight_img){ if(p.c%4) die("w align"); printf("L %d %lld\n", cur_tree, p.c/4); cur_tree++; dcount=0; V r; r.k=SCORE; return r; }
  if(p.k==FADDR && p.img==fernw_img){ printf("F %d %lld", cur_tree, p.c/4); for(int t: masks[p.fid]){ printf(" "); plin(V()); } printf("\n");
     for(int t: masks[p.fid]){ Test&T=tests[t]; printf("FT %d", cur_tree); V q; q.k=LIN; q.na=T.na; for(int i=0;i<T.na;i++){q.ti[i]=T.ti[i];q.to[i]=T.to[i];q.ts[i]=T.ts[i];} printf(" "); plin(q); printf(" %lld\n", T.thr);} 
     cur_tree++; V r; r.k=SCORE; return r; }
  fprintf(stderr,"deref kind %d img %d\n",p.k,p.img); die("deref"); return V();
}

static V store_[32];
static V load(const V& p){ if(p.k==PTR && p.img>=12){ return store_[p.img]; } return deref(p); }
static void storev(const V& p, const V& v){ if(p.k==PTR && p.img>=12){ if(p.img==12){ return; } if(p.img==14) printf("C %d %lld\n", cur_tree, v.c); store_[p.img]=v; return; } die("store"); }
struct R { V p; operator V() const { return load(p); } R& operator=(const V& v){ storev(p,v); return *this; } R& operator=(const R& r){ storev(p,(V)r); return *this; }
  R& operator+=(const V& v){ storev(p, load(p)+v); return *this; } R& operator++(){ storev(p, load(p)+V(1LL)); return *this; }
  R operator[](const V& i) const; };
static R operator*(const V& p){ R r; r.p=p; return r; }
static V& operator++(V& a){ a=a+V(1LL); return a; }
static V operator++(V& a,int){ V o=a; a=a+V(1LL); return o; }
static V& operator--(V& a){ a=a-V(1LL); return a; }

static V ADDR(const V& p, const V& i){ return p+i; }
struct VI { V b; V operator[](const V& i) const { return deref(b+i); } };
// operator[] on V via helper: we rewrite X[i] in text? no: provide member-like free function impossible; so V gets operator[] below
struct M { V l[8]; };
static M _mm_cvtsi32_si128(const V& v){ M m; for(int i=0;i<8;i++) m.l[i]=V(0LL); m.l[0]=v; return m; }
static M _mm_insert_epi16(M m, const V& v, int i){ m.l[i]=v; return m; }
static M _mm_sub_epi16(const M& a, const M& b){ M r; for(int i=0;i<8;i++) r.l[i]=a.l[i]-b.l[i]; return r; }
static M _mm_cmpgt_epi16(const M& d, const M& t){ M r; for(int i=0;i<8;i++){ Test T; const V& x=d.l[i]; if(x.k!=LIN) die("cmpgt nonlin"); T.na=x.na; for(int j=0;j<x.na;j++){T.ti[j]=x.ti[j];T.to[j]=x.to[j];T.ts[j]=x.ts[j];} if(t.l[i].k!=INT) die("thr"); T.thr=t.l[i].c - x.c; tests.push_back(T); r.l[i].k=TEST; r.l[i].fid=tests.size()-1; } return r; }
static V _mm_movemask_epi8(const M& m){ std::vector<int> ids; for(int i=0;i<8;i++){ if(m.l[i].k!=TEST) die("mask"); ids.push_back(m.l[i].fid);} masks.push_back(ids); V r; r.k=MASK; r.fid=masks.size()-1; return r; }
struct Tbl { V operator[](const V& m) const { if(m.k!=MASK) die("tbl"); V r; r.k=FIDX; r.fid=m.fid; r.c=1; return r; } };
static Tbl byte_180112750;
static M mkc(int a0,int a1,int a2,int a3,int a4,int a5,int a6,int a7){ M m; int a[8]={a0,a1,a2,a3,a4,a5,a6,a7}; for(int i=0;i<8;i++) m.l[i]=V((ll)a[i]); return m; }



struct VP { V p; VP(){} explicit VP(const V& v):p(v){} VP& operator=(const V& v){p=v; return *this;} VP& operator=(const R& r){p=(V)r; return *this;} operator V() const { return p; }
  R operator[](const V& i) const { R r; r.p=p+V(4LL)*i; return r; } };
static VP operator+(const VP& a, const V& k){ return VP(a.p+V(4LL)*k); }
static VP operator-(const VP& a, const V& k){ return VP(a.p-V(4LL)*k); }
static R operator*(const VP& a){ R r; r.p=a.p; return r; }

R V::operator[](const V& i) const { R r; r.p=*this+i; return r; }
R R::operator[](const V& i) const { R r; r.p=load(p)+V(4LL)*i; return r; }

